cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_excluding_tax\'),\'\"\',\'\') as float64),0) + ifnull(cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_tax\'),\'\"\',\'\') as float64),0) + ifnull(cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.credit_note_total_item_shipping_charge\'),\'\"\',\'\') as float64),0) + ifnull(cast(replace(JSON_EXTRACT_SCALAR(RI,\'$.total_item_selling_price\'),\'\"\',\'\') as float64),0) as TOTAL_RETURN_AMOUNT ,row_number() over (partition by Order_ID, Invoice_ID, REFERENCE_CODE, replace(JSON_EXTRACT_SCALAR(RI,\'$.suborder_id\'),\'\"\',\'\'),credit_note_id, credit_note_number order by cast(LAST_UPDATE_DATE as timestamp) desc) rw from maplemonk.easyecom_izf_RETURNS R left join UNNEST(ITEMS) RI ) where rw = 1; CREATE OR REPLACE TABLE izf-wh.maplemonk.IZF_easyecom_returns_fact_items AS SELECT IFNULL(FE.Source, \'NA\') AS Marketing_CHANNEL, FR.* FROM izf-wh.maplemonk.IZF_easyecom_returns_intermediate FR LEFT JOIN ( SELECT DISTINCT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, saleorderitemcode, Source FROM izf-wh.maplemonk.IZF_sales_consolidated ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE and FR.SUBORDER_NUM = FE.SALEORDERITEMCODE;",
